import org.mockito.internal.matchers.apachecommons.ReflectionEquals;
import org.mockito.internal.progress.HandyReturnValues;
import org.mockito.internal.progress.MockingProgress;
import org.mockito.internal.progress.ThreadSafeMockingProgress;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for Matchers.anyShort()
 */
public class Matchers_anyShort_TriageGen2Test {

    @Test
    public void testAnyShortReturnsZero() {
        // The implementation of anyShort() is: return reportMatcher(Any.ANY).returnZero();
        // Since it returns the result of returnZero() on a Matcher, 
        // for a short return type, this should result in 0.
        short result = Matchers.anyShort();
        assertEquals((short) 0, result);
    }
}
